using UnityEngine;

/// <summary>
/// 房间门 — 挂载在每个门 GO 上。
/// 门 GO 本身是 Trigger + 门贴图；Blocker 是 Solid Collider + 墙壁贴图。
/// 无连接时：隐藏门 GO、显示 Blocker，视觉上变回墙壁。
/// </summary>
public class RoomPortal : MonoBehaviour
{
    [Header("门配置")]
    public DoorDirection direction;
    public int targetRoomId = -1;

    [Header("组件引用")]
    [Tooltip("门 GO 的 SpriteRenderer (半透明门贴图)")]
    public SpriteRenderer doorSprite;

    [Tooltip("开门时激活的 Trigger Collider")]
    public Collider2D openTrigger;

    [Tooltip("关门/无连接时激活的阻挡物 — 实体碰撞体")]
    public GameObject doorBlocker;

    [Header("触发设置")]
    public string targetTag = "Player";

    private bool _locked;

    private void Awake()
    {
        if (doorSprite == null) doorSprite = GetComponent<SpriteRenderer>();
        if (openTrigger == null) openTrigger = GetComponent<Collider2D>();
        if (openTrigger != null) openTrigger.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (_locked) return;
        if (targetRoomId < 0) return;
        if (!other.CompareTag(targetTag)) return;
        if (MapManager.Instance == null) return;

        // 只有真正的主角才能触发传送（随从也是 Player tag，但不应该切换房间）
        if (other.GetComponent<PlayerStats>() == null) return;

        MapManager.Instance.SwitchRoom(targetRoomId, direction);
    }

    /// <summary>锁定/解锁门。locked=true: 启用 Blocker、禁用 Trigger + 隐藏门贴图。</summary>
    public void SetLocked(bool locked)
    {
        _locked = locked;

        if (openTrigger != null)
            openTrigger.enabled = !locked;

        if (doorSprite != null)
            doorSprite.enabled = !locked;

        if (doorBlocker != null)
            doorBlocker.SetActive(locked);
    }

    /// <summary>将此门永久隐藏为墙壁（无连接房间）。</summary>
    public void HideAsWall()
    {
        targetRoomId = -1;

        // 隐藏门的 Trigger + Sprite
        if (openTrigger != null) openTrigger.enabled = false;
        if (doorSprite != null) doorSprite.enabled = false;

        // 启用 Blocker 填充门洞
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 单房间管理器 — 管理单个房间的运行时状态。
/// 负责怪物生成、门锁定/解锁、道具生成等。
/// </summary>
public class RoomManager : MonoBehaviour
{
    [Header("组件引用")]
    public RoomRoot roomRoot;

    [Header("房间状态")]
    [SerializeField] private bool _isCleared;
    private bool _isFirstEnter = true;

    /// <summary>房间是否已清完怪物</summary>
    public bool IsCleared => _isCleared;

    /// <summary>是否首次进入</summary>
    public bool IsFirstEnter => _isFirstEnter;

    /// <summary>当前存活怪物列表</summary>
    private List<GameObject> _aliveEnemies = new();

    /// <summary>所有门 Portal 引用</summary>
    private List<RoomPortal> _portals = new();

    public event System.Action OnRoomCleared;

    private void Awake()
    {
        if (roomRoot == null)
            roomRoot = GetComponent<RoomRoot>();

        _portals.AddRange(GetComponentsInChildren<RoomPortal>());

        // 确保每次实例化都是首次进入状态 (防止序列化残留)
        _isFirstEnter = true;
        _isCleared = false;
    }

    /// <summary>玩家进入房间时调用</summary>
    public void OnPlayerEnter()
    {
        if (roomRoot == null) roomRoot = GetComponent<RoomRoot>();
        if (roomRoot == null || roomRoot.config == null) return;

        Debug.Log($"[RoomManager] Room{roomRoot.roomId} OnPlayerEnter: _isFirstEnter={_isFirstEnter}, enemyPool={roomRoot.config.enemyPool?.Count}, minEnemies={roomRoot.config.minEnemies}");

        if (_isFirstEnter)
        {
            _isFirstEnter = false;
            SpawnEnemies();
            Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

            if (_aliveEnemies.Count > 0)
            {
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} calling LockDoors...");
                LockDoors();
                Debug.Log($"[RoomManager] Room{roomRoot.roomId} LockDoors done.");
            }
        }
    }

    /// <summary>玩家离开房间时调用</summary>
    public void OnPlayerExit()
    {
        // 暂不需要特殊处理
    }

    /// <summary>锁定所有门 (启用阻挡物 + 禁用触发器)</summary>
    private void LockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(true);
        }
    }

    /// <summary>解锁所有门 (启用触发器 + 禁用阻挡物)</summary>
    private void UnlockDoors()
    {
        foreach (var portal in _portals)
        {
            if (portal != null)
                portal.SetLocked(false);
        }
    }

    /// <summary>生成怪物</summary>
    private void SpawnEnemies()
    {
        if (roomRoot == null || roomRoot.config == null) return;

        var cfg = roomRoot.config;
        if (cfg.enemyPool == null || cfg.enemyPool.Count == 0) return;

        // 按权重选择敌人
        int totalEnemies = Random.Range(cfg.minEnemies, cfg.maxEnemies + 1);
        int spawnPointCount = roomRoot.enemySpawnPoints != null ? roomRoot.enemySpawnPoints.Length : 0;

        if (spawnPointCount == 0)
        {
            Debug.LogWarning($"Room {roomRoot.roomId}: 没有敌人生成点");
            return;
        }

        // 随机选取生成点 (不重复)
        var availablePoints = new List<int>();
        for (int i = 0; i < spawnPointCount; i++)
            availablePoints.Add(i);
        Shuffle(availablePoints);

        int spawnCount = Mathf.Min(totalEnemies, availablePoints.Count);

        for (int i = 0; i < spawnCount; i++)
        {
            // 按权重随机选择敌人类型
            var entry = PickWeighted(cfg.enemyPool);
            if (entry == null || entry.enemyPrefab == null) continue;

            var spawnPoint = roomRoot.enemySpawnPoints[availablePoints[i]];
            var enemy = Instantiate(entry.enemyPrefab, spawnPoint.position, Quaternion.identity, transform);
            _aliveEnemies.Add(enemy);

            // 监听敌人死亡，使用 IEnemy 接口
            if (enemy.TryGetComponent<IEnemy>(out var ienemy))
            {
                ienemy.OnDied += () => OnEnemyDied(enemy);
                ienemy.OnAssimilated += (_) => OnEnemyAssimilated(enemy);
            }
        }

        Debug.Log($"Room {roomRoot.roomId}: 生成了 {spawnCount} 个敌人");
    }

    /// <summary>按权重随机选择</summary>
    private EnemySpawnEntry PickWeighted(List<EnemySpawnEntry> entries)
    {
        float totalWeight = 0f;
        foreach (var e in entries) totalWeight += e.weight;

        if (totalWeight <= 0f) return entries.Count > 0 ? entries[0] : null;

        float roll = Random.Range(0f, totalWeight);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative)
                return e;
        }
        return entries[^1];
    }

    /// <summary>敌人死亡回调</summary>
    private void OnEnemyDied(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>敌人被同化为随从（不再计入房间清空判定）</summary>
    private void OnEnemyAssimilated(GameObject enemy)
    {
        _aliveEnemies.Remove(enemy);

        if (_aliveEnemies.Count == 0)
        {
            OnAllEnemiesDefeated();
        }
    }

    /// <summary>所有敌人被击败</summary>
    private void OnAllEnemiesDefeated()
    {
        _isCleared = true;

        // 解锁门
        UnlockDoors();

        // 生成道具奖励
        SpawnItems();

        Debug.Log($"Room {roomRoot.roomId}: 已清空!");
        OnRoomCleared?.Invoke();
    }

    /// <summary>生成道具</summary>
    private void SpawnItems()
    {
        if (roomRoot == null || roomRoot.config == null) return;
        var cfg = roomRoot.config;
        if (cfg.itemPool == null || cfg.itemPool.Count == 0) return;

        int totalItems = Random.Range(cfg.minItems, cfg.maxItems + 1);
        int spawnPointCount = roomRoot.itemSpawnPoints != null ? roomRoot.itemSpawnPoints.Length : 0;
        if (spawnPointCount == 0) return;

        int spawnCount = Mathf.Min(totalItems, spawnPointCount);

        for (int i = 0; i < spawnCount; i++)
        {
            int idx = Random.Range(0, cfg.itemPool.Count);
            var itemPrefab = cfg.itemPool[idx];
            if (itemPrefab == null) continue;

            Instantiate(itemPrefab, roomRoot.itemSpawnPoints[i].position, Quaternion.identity, transform);
        }
    }

    /// <summary>协程: 轮询检查敌人死亡 (用于未继承 BaseEnemy 的敌人)</summary>
    private System.Collections.IEnumerator WatchEnemyDeath(GameObject enemy)
    {
        while (enemy != null)
        {
            yield return new WaitForSeconds(0.5f);
        }
        OnEnemyDied(null);
    }

    private static void Shuffle<T>(List<T> list)
    {
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (list[i], list[j]) = (list[j], list[i]);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间根节点 — 挂载在每个房间预制体的根 GameObject 上。
/// 管理房间的激活/隐藏、门位置查询、生成点等。
/// </summary>
public class RoomRoot : MonoBehaviour
{
    [Header("房间配置")]
    public RoomConfig config;

    [Header("房间 ID (运行时赋值)")]
    public int roomId;

    [Header("门 Transform (按方向索引: Top=0, Bottom=1, Left=2, Right=3)")]
    public Transform topDoor;
    public Transform bottomDoor;
    public Transform leftDoor;
    public Transform rightDoor;

    [Header("敌人生成点")]
    public Transform[] enemySpawnPoints;

    [Header("道具生成点")]
    public Transform[] itemSpawnPoints;

    [Header("房间边界 (用于摄像机)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    /// <summary>获取房间中心世界坐标</summary>
    public Vector2 Center => (Vector2)transform.position;

    /// <summary>获取房间边界矩形</summary>
    public Rect Bounds => new(Center - roomSize * 0.5f, roomSize);

    /// <summary>获取指定方向门的世界坐标</summary>
    public Vector3 GetDoorWorldPosition(DoorDirection dir)
    {
        var t = GetDoorTransform(dir);
        return t != null ? t.position : transform.position;
    }

    /// <summary>获取指定方向门的 Transform</summary>
    public Transform GetDoorTransform(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoor,
            DoorDirection.Bottom => bottomDoor,
            DoorDirection.Left => leftDoor,
            DoorDirection.Right => rightDoor,
            _ => null
        };
    }

    /// <summary>获取所有可用的门方向</summary>
    public List<DoorDirection> GetAvailableDoors()
    {
        var doors = new List<DoorDirection>();
        if (topDoor != null) doors.Add(DoorDirection.Top);
        if (bottomDoor != null) doors.Add(DoorDirection.Bottom);
        if (leftDoor != null) doors.Add(DoorDirection.Left);
        if (rightDoor != null) doors.Add(DoorDirection.Right);
        return doors;
    }

    private List<GameObject> _childrenCache = new();

    /// <summary>激活房间 (显示所有子物体)</summary>
    public void Activate()
    {
        gameObject.SetActive(true);
    }

    /// <summary>隐藏房间</summary>
    public void Deactivate()
    {
        gameObject.SetActive(false);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireCube(Center, roomSize);

        if (config != null)
        {
            var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
            foreach (var dir in dirs)
            {
                if (config.HasDoor(dir))
                {
                    Gizmos.color = Color.yellow;
                    Gizmos.DrawSphere(GetDoorWorldPosition(dir), 0.3f);
                }
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 门方向枚举
/// </summary>
public enum DoorDirection
{
    Top,
    Bottom,
    Left,
    Right
}

/// <summary>
/// 门连接数据 — 描述一个门在房间内的位置
/// </summary>
[System.Serializable]
public class DoorConnection
{
    [Tooltip("门的方向")]
    public DoorDirection direction;

    [Tooltip("门在房间内的本地坐标")]
    public Vector2 localPosition;
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间图节点 — 代表一个房间在图中的信息
/// </summary>
public class RoomNode
{
    /// <summary>房间 ID (唯一)</summary>
    public int roomId;

    /// <summary>房间配置</summary>
    public RoomConfig config;

    /// <summary>房间类型</summary>
    public RoomType roomType;

    /// <summary>房间在世界空间中的位置 (中心点)</summary>
    public Vector2 worldPosition;

    /// <summary>该房间已激活使用的门</summary>
    public List<DoorConnection> activeDoors = new();

    /// <summary>图连接: targetRoomId -> 通过哪个方向的门连接</summary>
    public Dictionary<int, DoorDirection> connections = new();

    /// <summary>房间的矩形边界 (世界坐标)</summary>
    public Rect Bounds => new(worldPosition - config.roomSize * 0.5f, config.roomSize);

    /// <summary>获取指定方向门的世界坐标</summary>
    public Vector2 GetDoorWorldPosition(DoorDirection dir)
    {
        return worldPosition + config.GetDoorOffset(dir);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间图 — 描述所有房间及其连接关系
/// </summary>
[System.Serializable]
public class RoomGraph
{
    /// <summary>所有房间节点</summary>
    public List<RoomNode> nodes = new();

    /// <summary>起始房间 ID</summary>
    public int startRoomId;

    /// <summary>出口房间 ID</summary>
    public int exitRoomId;

    private int _nextId;

    /// <summary>添加房间节点</summary>
    public RoomNode AddNode(RoomConfig config, RoomType type, Vector2 worldPos)
    {
        var node = new RoomNode
        {
            roomId = _nextId++,
            config = config,
            roomType = type,
            worldPosition = worldPos
        };
        nodes.Add(node);
        return node;
    }

    /// <summary>连接两个房间的门</summary>
    public void Connect(int fromId, int toId, DoorDirection fromDir, DoorDirection toDir)
    {
        var from = GetNode(fromId);
        var to = GetNode(toId);
        if (from == null || to == null) return;

        from.connections[toId] = fromDir;
        to.connections[fromId] = toDir;
    }

    /// <summary>根据 ID 获取节点</summary>
    public RoomNode GetNode(int id)
    {
        return nodes.Find(n => n.roomId == id);
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomNode> GetAdjacent(int id)
    {
        var node = GetNode(id);
        if (node == null) return new List<RoomNode>();

        var result = new List<RoomNode>();
        foreach (var conn in node.connections)
        {
            var adj = GetNode(conn.Key);
            if (adj != null) result.Add(adj);
        }
        return result;
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图生成器 — 基于配置生成房间图和布局
/// 
/// 算法:
/// 1. 从 Start 房间开始 (放置在中心)
/// 2. BFS 扩展: 每次从已放置房间的未占用门出发
/// 3. 随机选取匹配门方向的房间配置
/// 4. 根据门的本地坐标对齐相邻房间
/// 5. Boss 房间放在最远端, Exit 放在 Boss 旁边
/// </summary>
public class MapGenerator
{
    private MapConfig _config;
    private int _seed;

    public MapGenerator(MapConfig config)
    {
        _config = config;
    }

    /// <summary>生成房间图</summary>
    public RoomGraph Generate(int seed)
    {
        _seed = seed;
        if (_seed != 0)
            Random.InitState(_seed);
        else
            Random.InitState(System.DateTime.Now.Millisecond);

        var graph = new RoomGraph();

        if (_config.startRoom == null)
        {
            Debug.LogError("MapGenerator: startRoom 未配置!");
            return graph;
        }

        // 1. 放置 Start 房间在中心
        var startNode = graph.AddNode(_config.startRoom, RoomType.Start, Vector2.zero);
        graph.startRoomId = startNode.roomId;

        // 2. 构建需要生成的房间类型队列 (打乱顺序)
        var roomTypeQueue = BuildRoomTypeQueue();

        // 3. BFS 放置
        var placedOpenDoors = new List<(int roomId, DoorDirection dir)>();
        AddOpenDoors(placedOpenDoors, startNode);

        var placedRoomIds = new List<int> { startNode.roomId };
        int typeQueueIndex = 0;
        int failsafe = 0;
        const int maxAttempts = 200;

        while (typeQueueIndex < roomTypeQueue.Count && placedOpenDoors.Count > 0 && failsafe < maxAttempts)
        {
            failsafe++;

            // 随机选一个开放的门
            int doorIdx = Random.Range(0, placedOpenDoors.Count);
            var (anchorId, anchorDir) = placedOpenDoors[doorIdx];
            placedOpenDoors.RemoveAt(doorIdx);

            var anchorNode = graph.GetNode(anchorId);
            if (anchorNode == null) continue;

            RoomType targetType = roomTypeQueue[typeQueueIndex];
            RoomConfig[] pool = _config.GetPoolForType(targetType);

            if (pool == null || pool.Length == 0)
            {
                // 跳过没有配置该类型池的类型
                typeQueueIndex++;
                // 把这个门放回去，留给下一个房间
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 随机选取匹配门方向的房间
            var targetDir = RoomConfig.OppositeDir(anchorDir);
            var candidates = new List<RoomConfig>();
            foreach (var rc in pool)
            {
                if (rc != null && rc.HasDoor(targetDir))
                    candidates.Add(rc);
            }

            if (candidates.Count == 0)
            {
                // 没有可用的候选，跳过
                continue;
            }

            var chosenConfig = candidates[Random.Range(0, candidates.Count)];

            // 计算新房间位置
            Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(anchorDir);
            Vector2 targetDoorLocal = chosenConfig.GetDoorOffset(targetDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            // 碰撞检测
            var newBounds = new Rect(newPos - chosenConfig.roomSize * 0.5f, chosenConfig.roomSize);
            if (OverlapsAny(graph, newBounds))
            {
                // 放回门，稍后重试
                placedOpenDoors.Add((anchorId, anchorDir));
                continue;
            }

            // 成功放置
            var newNode = graph.AddNode(chosenConfig, targetType, newPos);
            graph.Connect(anchorId, newNode.roomId, anchorDir, targetDir);
            placedRoomIds.Add(newNode.roomId);

            // 将新房间的未连接门加入开放列表
            AddOpenDoors(placedOpenDoors, newNode, targetDir);

            // 如果是 Boss 房间，紧挨着放置 Exit
            if (targetType == RoomType.Boss && _config.exitRoom != null)
            {
                typeQueueIndex++;
                if (typeQueueIndex < roomTypeQueue.Count && roomTypeQueue[typeQueueIndex] == RoomType.Exit)
                {
                    if (TryPlaceExitRoom(graph, newNode, placedOpenDoors, placedRoomIds))
                        typeQueueIndex++;
                }
                continue;
            }

            typeQueueIndex++;
        }

        // 如果 Exit 还没放置，尝试最后放置
        if (graph.exitRoomId == 0 && _config.exitRoom != null)
        {
            PlaceExitRoomAtEnd(graph, placedOpenDoors);
        }

        if (failsafe >= maxAttempts)
            Debug.LogWarning("MapGenerator: 达到最大尝试次数，可能未生成全部房间");

        Debug.Log($"MapGenerator: 生成了 {graph.nodes.Count} 个房间 (预期 {_config.TotalRooms})");
        return graph;
    }

    /// <summary>构建房间类型队列 (打乱)</summary>
    private List<RoomType> BuildRoomTypeQueue()
    {
        var queue = new List<RoomType>();

        for (int i = 0; i < _config.normalRoomCount; i++)
            queue.Add(RoomType.Normal);
        for (int i = 0; i < _config.treasureRoomCount; i++)
            queue.Add(RoomType.Treasure);
        for (int i = 0; i < _config.shopRoomCount; i++)
            queue.Add(RoomType.Shop);
        // Boss 放最后，Exit 放 Boss 之后
        for (int i = 0; i < _config.bossRoomCount; i++)
            queue.Add(RoomType.Boss);
        // Exit 在 Boss 之后
        if (_config.exitRoom != null)
            queue.Add(RoomType.Exit);

        // 洗牌 (但不打乱 Boss 和 Exit 的相对顺序)
        // 把除了最后两个 (Boss + Exit) 的打乱
        int shuffleCount = queue.Count;
        if (_config.bossRoomCount > 0 && _config.exitRoom != null)
            shuffleCount -= 2;

        for (int i = 0; i < shuffleCount; i++)
        {
            int j = Random.Range(i, shuffleCount);
            (queue[i], queue[j]) = (queue[j], queue[i]);
        }

        return queue;
    }

    /// <summary>尝试在 Boss 房间旁放置 Exit</summary>
    private bool TryPlaceExitRoom(RoomGraph graph, RoomNode bossNode, 
        List<(int roomId, DoorDirection dir)> openDoors, List<int> placedRoomIds)
    {
        var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
        Shuffle(dirs);

        foreach (var dir in dirs)
        {
            var oppositeDir = RoomConfig.OppositeDir(dir);

            if (!_config.exitRoom.HasDoor(oppositeDir))
                continue;

            // 检查 Boss 房间该方向是否已有连接
            if (bossNode.connections.ContainsValue(dir))
                continue;

            Vector2 anchorDoorWorld = bossNode.GetDoorWorldPosition(dir);
            Vector2 targetDoorLocal = _config.exitRoom.GetDoorOffset(oppositeDir);
            Vector2 newPos = anchorDoorWorld - targetDoorLocal;

            var newBounds = new Rect(newPos - _config.exitRoom.roomSize * 0.5f, _config.exitRoom.roomSize);
            if (OverlapsAny(graph, newBounds))
                continue;

            var exitNode = graph.AddNode(_config.exitRoom, RoomType.Exit, newPos);
            graph.Connect(bossNode.roomId, exitNode.roomId, dir, oppositeDir);
            graph.exitRoomId = exitNode.roomId;
            return true;
        }

        return false;
    }

    /// <summary>最后放置 Exit 房间</summary>
    private void PlaceExitRoomAtEnd(RoomGraph graph, 
        List<(int roomId, DoorDirection dir)> openDoors)
    {
        if (graph.exitRoomId != 0) return;

        // 找 Boss 房间
        RoomNode bossNode = null;
        foreach (var n in graph.nodes)
        {
            if (n.roomType == RoomType.Boss)
            {
                bossNode = n;
                break;
            }
        }

        if (bossNode != null)
        {
            if (TryPlaceExitRoom(graph, bossNode, openDoors, null))
                return;
        }

        // 回退: 从任意开放的门放置
        foreach (var openDoor in openDoors)
        {
            var anchorNode = graph.GetNode(openDoor.roomId);
            if (anchorNode == null) continue;

            var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
            Shuffle(dirs);

            foreach (var dir in dirs)
            {
                var opp = RoomConfig.OppositeDir(dir);
                if (!_config.exitRoom.HasDoor(opp)) continue;

                Vector2 anchorDoorWorld = anchorNode.GetDoorWorldPosition(dir);
                Vector2 targetDoorLocal = _config.exitRoom.GetDoorOffset(opp);
                Vector2 newPos = anchorDoorWorld - targetDoorLocal;
                var newBounds = new Rect(newPos - _config.exitRoom.roomSize * 0.5f, _config.exitRoom.roomSize);
                if (OverlapsAny(graph, newBounds)) continue;

                var exitNode = graph.AddNode(_config.exitRoom, RoomType.Exit, newPos);
                graph.Connect(anchorNode.roomId, exitNode.roomId, dir, opp);
                graph.exitRoomId = exitNode.roomId;
                return;
            }
        }
    }

    /// <summary>将房间的未使用门加入开放列表</summary>
    private void AddOpenDoors(List<(int roomId, DoorDirection dir)> openDoors, RoomNode node, 
        DoorDirection? excludeDir = null)
    {
        var allDirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
        foreach (var dir in allDirs)
        {
            if (excludeDir.HasValue && dir == excludeDir.Value) continue;
            if (node.config.HasDoor(dir))
                openDoors.Add((node.roomId, dir));
        }
    }

    /// <summary>检查矩形是否与已有房间重叠。
    /// 相邻房间共享边界 (edge-to-edge) 不算重叠，只有真正交叉才冲突。
    /// roomSpacing 用作最小间隔。</summary>
    private bool OverlapsAny(RoomGraph graph, Rect bounds)
    {
        // 缩一圈来确保最小间距 (只对真正相交的生效)
        float shrink = _config.roomSpacing * 0.5f;
        var checkRect = new Rect(
            bounds.x + shrink,
            bounds.y + shrink,
            bounds.width - shrink * 2,
            bounds.height - shrink * 2
        );

        foreach (var node in graph.nodes)
        {
            var otherRect = new Rect(
                node.Bounds.x + shrink,
                node.Bounds.y + shrink,
                node.Bounds.width - shrink * 2,
                node.Bounds.height - shrink * 2
            );

            if (checkRect.Overlaps(otherRect))
                return true;
        }
        return false;
    }

    private static void Shuffle<T>(T[] arr)
    {
        for (int i = arr.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (arr[i], arr[j]) = (arr[j], arr[i]);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 地图管理器 (单例) — 新地图系统的核心管理器。
/// 替代旧的 TileManager。
/// 负责: 地图生成、房间实例化、房间切换、玩家追踪。
/// </summary>
public class MapManager : MonoBehaviour
{
    public static MapManager Instance { get; private set; }

    [Header("地图配置")]
    [SerializeField] private MapConfig _mapConfig;

    [Header("运行时")]
    [SerializeField] private int _currentRoomId;
    [SerializeField] private bool _isSwitchingRoom;

    // 内部状态
    private RoomGraph _roomGraph;
    private MapGenerator _generator;
    private Dictionary<int, RoomRoot> _roomInstances = new();
    private RoomRoot _currentRoom;
    private Coroutine _switchCoroutine;
    private Transform _playerTransform;

    /// <summary>玩家从门进入新房间时的内缩距离 (避免立刻再次触发门)</summary>
    [SerializeField] private float _doorEntryOffset = 1.5f;

    // 事件
    public event System.Action<int, int> OnRoomChanged; // (fromRoomId, toRoomId)
    public event System.Action<int, int> OnRoomSwitchStarted;
    public event System.Action<int> OnRoomSwitchCompleted; // (newRoomId)

    // 属性
    public RoomRoot CurrentRoom => _currentRoom;
    public int CurrentRoomId => _currentRoomId;
    public bool IsSwitchingRoom => _isSwitchingRoom;
    public RoomGraph RoomGraph => _roomGraph;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    private void Start()
    {
        // 缓存玩家 Transform
        var playerGo = GameObject.FindGameObjectWithTag("Player");
        if (playerGo != null)
            _playerTransform = playerGo.transform;

        if (_mapConfig != null)
        {
            GenerateMap();
        }
        else
        {
            Debug.LogError("MapManager: MapConfig 未配置!");
        }
    }

    // ==================== 地图生成 ====================

    /// <summary>生成并实例化地图</summary>
    public void GenerateMap()
    {
        if (_mapConfig == null)
        {
            Debug.LogError("MapManager: MapConfig 为空，无法生成地图");
            return;
        }

        // 清理旧实例
        ClearExistingRooms();

        // 设置随机种子
        int seed = _mapConfig.useRandomSeed ? Random.Range(0, int.MaxValue) : _mapConfig.seed;

        // 生成房间图
        _generator = new MapGenerator(_mapConfig);
        _roomGraph = _generator.Generate(seed);

        // 实例化所有房间
        foreach (var node in _roomGraph.nodes)
        {
            InstantiateRoom(node);
        }

        // 设置所有 RoomPortal 的目标房间
        SetupPortals();

        // 先隐藏所有房间
        foreach (var room in _roomInstances.Values)
        {
            room.Deactivate();
        }

        // 激活起始房间
        var startNode = _roomGraph.GetNode(_roomGraph.startRoomId);
        if (startNode != null && _roomInstances.TryGetValue(_roomGraph.startRoomId, out var startRoom))
        {
            startRoom.Activate();
            _currentRoomId = startRoom.roomId;
            _currentRoom = startRoom;

            // 通知 RoomManager 玩家进入
            var roomMgr = startRoom.GetComponent<RoomManager>();
            if (roomMgr != null)
                roomMgr.OnPlayerEnter();
        }

        Debug.Log($"MapManager: 地图生成完成 — {_roomGraph.nodes.Count} 个房间, Start={_roomGraph.startRoomId}");
    }

    /// <summary>实例化单个房间</summary>
    private void InstantiateRoom(RoomNode node)
    {
        var prefab = node.config.GetRandomPrefab();
        if (prefab == null)
        {
            Debug.LogError($"MapManager: RoomConfig '{node.config.name}' 没有预制体!");
            return;
        }

        var go = Instantiate(prefab, node.worldPosition, Quaternion.identity, transform);
        go.name = $"Room_{node.roomId}_{node.roomType}";

        var root = go.GetComponent<RoomRoot>();
        if (root == null)
        {
            root = go.AddComponent<RoomRoot>();
        }

        root.config = node.config;
        root.roomId = node.roomId;

        // 确保有 RoomManager
        var roomMgr = go.GetComponent<RoomManager>();
        if (roomMgr == null)
            go.AddComponent<RoomManager>();

        _roomInstances[node.roomId] = root;
    }

    /// <summary>设置所有门的连接目标；无连接的门伪装为墙壁。</summary>
    private void SetupPortals()
    {
        foreach (var node in _roomGraph.nodes)
        {
            if (!_roomInstances.TryGetValue(node.roomId, out var root))
                continue;

            var portals = root.GetComponentsInChildren<RoomPortal>(true);
            foreach (var portal in portals)
            {
                // 查找匹配的连接
                bool connected = false;
                foreach (var conn in node.connections)
                {
                    if (conn.Value == portal.direction)
                    {
                        portal.targetRoomId = conn.Key;
                        connected = true;
                        break;
                    }
                }

                if (!connected)
                {
                    portal.HideAsWall();
                }
            }
        }
    }

    // ==================== 房间切换 ====================

    /// <summary>切换到目标房间，玩家从指定方向的门进入</summary>
    public void SwitchRoom(int targetRoomId, DoorDirection entryDir)
    {
        if (_isSwitchingRoom) return;
        if (targetRoomId == _currentRoomId) return;
        if (!_roomInstances.TryGetValue(targetRoomId, out var targetRoom)) return;

        StartCoroutine(SwitchRoomRoutine(targetRoomId, targetRoom, entryDir));
    }

    private IEnumerator SwitchRoomRoutine(int targetRoomId, RoomRoot targetRoom, DoorDirection entryDir)
    {
        _isSwitchingRoom = true;
        int fromRoomId = _currentRoomId;

        OnRoomSwitchStarted?.Invoke(fromRoomId, targetRoomId);

        // 通知旧房间玩家离开
        if (_currentRoom != null)
        {
            var oldMgr = _currentRoom.GetComponent<RoomManager>();
            oldMgr?.OnPlayerExit();
        }

        // 激活新房间
        targetRoom.Activate();

        // 传送玩家到目标房间入口 (反方向门的内侧)
        DoorDirection targetEntryDir = RoomConfig.OppositeDir(entryDir);
        TeleportPlayerToDoor(targetRoom, targetEntryDir);

        // 通知新房间玩家进入
        var newMgr = targetRoom.GetComponent<RoomManager>();
        newMgr?.OnPlayerEnter();

        // 更新状态
        _currentRoom = targetRoom;
        _currentRoomId = targetRoomId;

        // 等待摄像机过渡完成
        var cameraCtrl = Camera.main != null ? Camera.main.GetComponent<RoomCameraController>() : null;
        if (cameraCtrl != null)
        {
            bool transitionDone = false;
            cameraCtrl.MoveToRoom(targetRoom, () => transitionDone = true);
            yield return new WaitUntil(() => transitionDone);
        }

        // 隐藏旧房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Key != _currentRoomId)
                kvp.Value.Deactivate();
        }

        _isSwitchingRoom = false;
        OnRoomChanged?.Invoke(fromRoomId, targetRoomId);
        OnRoomSwitchCompleted?.Invoke(targetRoomId);

        Debug.Log($"MapManager: 切换到房间 {targetRoomId} ({targetRoom.config.roomType})");
    }

    /// <summary>将玩家传送到目标房间的门内侧</summary>
    private void TeleportPlayerToDoor(RoomRoot room, DoorDirection entryDir)
    {
        if (_playerTransform == null)
        {
            var playerGo = GameObject.FindGameObjectWithTag("Player");
            if (playerGo != null) _playerTransform = playerGo.transform;
        }
        if (_playerTransform == null) return;

        Vector2 doorLocal = room.config.GetDoorOffset(entryDir);
        Vector2 worldPos = room.Center + doorLocal;

        // 向外侧偏移内缩距离，防止立刻再次触发门
        Vector2 inwardDir = entryDir switch
        {
            DoorDirection.Top => Vector2.down,
            DoorDirection.Bottom => Vector2.up,
            DoorDirection.Left => Vector2.right,
            DoorDirection.Right => Vector2.left,
            _ => Vector2.zero
        };

        Vector2 targetPos = worldPos + inwardDir * _doorEntryOffset;

        // 传送玩家
        TeleportRigidbody(_playerTransform, targetPos);

        // 传送所有随从到玩家周围，并切换到新房间父节点
        TeleportFollowers(targetPos, room.transform);
    }

    /// <summary>安全传送 Transform（优先通过 Rigidbody2D.position）</summary>
    private static void TeleportRigidbody(Transform t, Vector2 targetPos)
    {
        if (t == null) return;
        var rb = t.GetComponent<Rigidbody2D>();
        if (rb != null)
        {
            rb.velocity = Vector2.zero;
            rb.position = targetPos;
        }
        else
        {
            t.position = targetPos;
        }
    }

    /// <summary>将所有活跃随从传送到玩家前方一字排开，并切到目标房间父节点</summary>
    private static void TeleportFollowers(Vector2 playerPos, Transform newParent)
    {
        var followers = EnemyFollower.ActiveFollowers;
        for (int i = 0; i < followers.Count; i++)
        {
            float offsetY = (i - (followers.Count - 1) / 2f) * 1.5f;
            Vector2 targetPos = playerPos + new Vector2(0.5f, offsetY);
            followers[i].transform.SetParent(newParent, true);
            TeleportRigidbody(followers[i].transform, targetPos);
        }
    }

    // ==================== 查询 API ====================

    /// <summary>根据 ID 获取房间</summary>
    public RoomRoot GetRoom(int roomId)
    {
        _roomInstances.TryGetValue(roomId, out var room);
        return room;
    }

    /// <summary>获取相邻房间列表</summary>
    public List<RoomRoot> GetAdjacentRooms(int roomId)
    {
        var result = new List<RoomRoot>();
        var node = _roomGraph?.GetNode(roomId);
        if (node == null) return result;

        foreach (var conn in node.connections)
        {
            if (_roomInstances.TryGetValue(conn.Key, out var room))
                result.Add(room);
        }
        return result;
    }

    /// <summary>确保所有门的连接正确 (在编辑器修改后调用)</summary>
    public void RefreshPortals()
    {
        SetupPortals();
    }

    // ==================== 辅助 ====================

    private void ClearExistingRooms()
    {
        // 1. 清理已追踪的房间
        foreach (var kvp in _roomInstances)
        {
            if (kvp.Value != null)
                DestroyImmediate(kvp.Value.gameObject);
        }
        _roomInstances.Clear();

        // 2. 清理残余子物体 (场景中保存的旧房间)
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            var child = transform.GetChild(i).gameObject;
            if (child.GetComponent<RoomRoot>() != null)
                DestroyImmediate(child);
        }

        _roomGraph = null;
        _currentRoom = null;
    }

    /// <summary>在编辑器中重新生成 (通过 Context Menu 调用)</summary>
    [ContextMenu("Regenerate Map")]
    public void RegenerateMap()
    {
        ClearExistingRooms();
        GenerateMap();
    }
}

/// <summary>房间类型枚举</summary>
public enum RoomType
{
    Start,     // 出生点，小房间
    Normal,    // 标准战斗房间
    Treasure,  // 宝箱房间
    Boss,      // Boss房间
    Shop,      // 商店
    Exit       // 出口/楼梯
}

using System.Collections.Generic;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间配置 — 定义某一类房间的通用参数 + 多个可选预制体变体
/// </summary>
[CreateAssetMenu(fileName = "RoomConfig", menuName = "Map/Room Config")]
public class RoomConfig : ScriptableObject
{
    [Header("基础信息")]
    [Tooltip("房间类型")]
    public RoomType roomType;

    [Tooltip("可选房间预制体列表 (生成时随机选取一个)")]
    public GameObject[] roomPrefabs;

    [Tooltip("难度等级 (影响怪物属性缩放等)")]
    public int difficultyLevel = 1;

    [Header("连接点 — 该房间有哪些方向的门")]
    public bool hasTopDoor;
    public bool hasBottomDoor;
    public bool hasLeftDoor;
    public bool hasRightDoor;

    [Header("房间尺寸 (世界单位，用于摄像机边界和布局计算)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    [Header("门在房间内的本地坐标偏移")]
    public Vector2 topDoorOffset = new Vector2(0f, 6f);
    public Vector2 bottomDoorOffset = new Vector2(0f, -6f);
    public Vector2 leftDoorOffset = new Vector2(-10f, 0f);
    public Vector2 rightDoorOffset = new Vector2(10f, 0f);

    [Header("怪物生成")]
    [Tooltip("可选怪物池")]
    public List<EnemySpawnEntry> enemyPool = new();

    [Tooltip("最少生成怪物数")]
    public int minEnemies = 1;

    [Tooltip("最多生成怪物数")]
    public int maxEnemies = 3;

    [Header("道具生成")]
    [Tooltip("可选道具池")]
    public List<GameObject> itemPool = new();

    [Tooltip("最少道具数")]
    public int minItems = 0;

    [Tooltip("最多道具数")]
    public int maxItems = 2;

    /// <summary>获取指定方向门的本地坐标偏移</summary>
    public Vector2 GetDoorOffset(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoorOffset,
            DoorDirection.Bottom => bottomDoorOffset,
            DoorDirection.Left => leftDoorOffset,
            DoorDirection.Right => rightDoorOffset,
            _ => Vector2.zero
        };
    }

    /// <summary>检查是否有指定方向的门</summary>
    public bool HasDoor(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => hasTopDoor,
            DoorDirection.Bottom => hasBottomDoor,
            DoorDirection.Left => hasLeftDoor,
            DoorDirection.Right => hasRightDoor,
            _ => false
        };
    }

    /// <summary>获取门的相反方向</summary>
    public static DoorDirection OppositeDir(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => DoorDirection.Bottom,
            DoorDirection.Bottom => DoorDirection.Top,
            DoorDirection.Left => DoorDirection.Right,
            DoorDirection.Right => DoorDirection.Left,
            _ => DoorDirection.Top
        };
    }

    /// <summary>从预制体池中随机选取一个。池为空时返回 null。</summary>
    public GameObject GetRandomPrefab()
    {
        if (roomPrefabs == null || roomPrefabs.Length == 0) return null;
        return roomPrefabs[Random.Range(0, roomPrefabs.Length)];
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// 房间摄像机控制器 — 固定房间视角 + 房间切换平滑滑动。
/// 挂载在 MainCamera 上。
/// 
/// 行为:
/// - 在房间中: 摄像机固定在房间中心，orthographicSize = 根据房间大小自动计算
/// - 房间切换: 平滑滑动到新房间中心 (0.5s)
/// - 过渡期间通知 MapManager 锁定玩家输入
/// </summary>
[RequireComponent(typeof(Camera))]
public class RoomCameraController : MonoBehaviour
{
    [Header("过渡设置")]
    [Tooltip("房间切换过渡时长 (秒)")]
    public float transitionDuration = 0.5f;

    [Tooltip("过渡曲线")]
    public AnimationCurve transitionCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);

    [Header("视角设置")]
    [Tooltip("摄像机 Orthographic Size 与房间高度的比例 (1.0 = 正好包住房间内高，1.2 = 含墙壁+门边距)")]
    public float sizeScale = 1.2f;

    [Tooltip("最小 Orthographic Size")]
    public float minOrthoSize = 5f;

    [Tooltip("最大 Orthographic Size")]
    public float maxOrthoSize = 25f;

    private Camera _cam;
    private Vector3 _targetPosition;
    private float _targetOrthoSize;
    private bool _isTransitioning;
    private Coroutine _transitionCoroutine;
    private RoomRoot _currentRoom;

    private void Awake()
    {
        _cam = GetComponent<Camera>();
        _targetPosition = transform.position;
        _targetOrthoSize = _cam.orthographicSize;
    }

    private void LateUpdate()
    {
        if (!_isTransitioning)
        {
            // 固定模式：直接锁定在目标位置
            transform.position = _targetPosition;
            _cam.orthographicSize = _targetOrthoSize;
        }
    }

    /// <summary>切换摄像机到目标房间</summary>
    /// <param name="room">目标房间</param>
    /// <param name="onComplete">过渡完成回调</param>
    public void MoveToRoom(RoomRoot room, System.Action onComplete = null)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z; // 保持 Z 轴

        // 计算合适的 Orthographic Size
        float targetSize = CalculateOrthoSize(room);

        if (transitionDuration <= 0f || _targetPosition == roomCenter)
        {
            // 瞬间切换
            _targetPosition = roomCenter;
            _targetOrthoSize = targetSize;
            onComplete?.Invoke();
            return;
        }

        // 平滑过渡
        if (_transitionCoroutine != null)
            StopCoroutine(_transitionCoroutine);
        _transitionCoroutine = StartCoroutine(TransitionRoutine(roomCenter, targetSize, onComplete));
    }

    /// <summary>根据房间大小计算合适的 Orthographic Size。</summary>
    /// <remarks>房间视觉范围 = roomSize + 四周墙壁(0.5×2=1)。取高宽中较严的方向，确保全覆盖。</remarks>
    private float CalculateOrthoSize(RoomRoot room)
    {
        // 含墙壁的完整视觉尺寸
        float visualW = room.roomSize.x + 1f;
        float visualH = room.roomSize.y + 1f;

        // Orthographic Size = half height → 纵向覆盖需要 visualH/2
        float sizeFromHeight = visualH * 0.5f * sizeScale;
        // 横向覆盖需要 visualW/2 / aspect
        float sizeFromWidth = visualW * 0.5f * sizeScale / _cam.aspect;
        float size = Mathf.Max(sizeFromHeight, sizeFromWidth);
        return Mathf.Clamp(size, minOrthoSize, maxOrthoSize);
    }

    /// <summary>平滑过渡协程</summary>
    private IEnumerator TransitionRoutine(Vector3 targetPos, float targetSize, System.Action onComplete)
    {
        _isTransitioning = true;

        Vector3 startPos = transform.position;
        float startSize = _cam.orthographicSize;

        float elapsed = 0f;

        while (elapsed < transitionDuration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / transitionDuration);
            float curveT = transitionCurve.Evaluate(t);

            transform.position = Vector3.Lerp(startPos, targetPos, curveT);
            _cam.orthographicSize = Mathf.Lerp(startSize, targetSize, curveT);

            yield return null;
        }

        // 最终值精确设置
        transform.position = targetPos;
        _cam.orthographicSize = targetSize;
        _targetPosition = targetPos;
        _targetOrthoSize = targetSize;

        _isTransitioning = false;
        onComplete?.Invoke();
    }

    /// <summary>立即跳转到房间 (无过渡)</summary>
    public void SnapToRoom(RoomRoot room)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z;

        transform.position = roomCenter;
        _targetPosition = roomCenter;
        _targetOrthoSize = CalculateOrthoSize(room);
        _cam.orthographicSize = _targetOrthoSize;
    }

    public RoomRoot CurrentRoom => _currentRoom;
    public bool IsTransitioning => _isTransitioning;
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButtonDown(0))
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed;
    }
}

using UnityEngine;

/// <summary>
/// 随从行为组件：接管被同化敌人的 AI，跟随玩家 + 搜索并攻击其他敌人。
/// 由 EnemyCore.Assimilate() 激活。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class EnemyFollower : MonoBehaviour
{
    [Header("随从参数")]
    [SerializeField] private float _followDistance = 2f;
    [SerializeField] private float _detectionRange = 8f;
    [SerializeField] private float _attackRange = 2f;
    [SerializeField] private float _followSpeed = 3f;
    [Tooltip("离玩家超过此距离时直接传送到身边，防止掉队")]
    [SerializeField] private float _maxTeleportDistance = 12f;

    private Transform _player;
    private EnemyCore _core;
    private EnemyMovement _movement;
    private IAttackBehavior _attackBehavior;
    private EnemySkillManager _skillManager;
    private bool _isActive;

    /// <summary>所有活跃随从列表（供 MapManager 查询，避免 FindObjectsByType）</summary>
    public static readonly System.Collections.Generic.List<EnemyFollower> ActiveFollowers = new();

    private void OnEnable()
    {
        ActiveFollowers.Add(this);
    }

    private void OnDisable()
    {
        ActiveFollowers.Remove(this);
        if (_core != null && _core.Health != null)
            _core.Health.OnDied -= HandleDeath;
    }

    private void Awake()
    {
        _core = GetComponent<EnemyCore>();
    }

    /// <summary>
    /// 激活随从模式。
    /// </summary>
    public void Activate(Transform player)
    {
        _player = player;
        _isActive = true;

        _movement = _core.Movement;
        _attackBehavior = _core.AttackBehavior;
        _skillManager = _core.SkillManager;

        if (_movement != null)
            _movement.MoveSpeed = _followSpeed;

        // 远程攻击的随从需要以 OwnerType.Player 发射投射物，才能命中 Enemy tag
        if (_attackBehavior is RangedAttack ranged)
            ranged.projectileOwnerType = Projectile.OwnerType.Player;

        // 近战攻击同样需要切换阵营，避免误伤玩家和其他随从
        if (_attackBehavior is MeleeAttack melee)
            melee.ownerType = Projectile.OwnerType.Player;

        // 接管死亡事件（EnemyCore.Assimilate 已清除原有订阅）
        if (_core.Health != null)
            _core.Health.OnDied += HandleDeath;
    }

    private void Update()
    {
        if (!_isActive || _player == null) return;
        if (_core.Health != null && _core.Health.IsDead) return;

        Vector2 pos = transform.position;
        Vector2 playerPos = _player.position;

        // 离玩家过远 → 直接传送到身边，防止掉队或被卡住
        float sqrDistToPlayer = (pos - playerPos).sqrMagnitude;
        if (sqrDistToPlayer > _maxTeleportDistance * _maxTeleportDistance)
        {
            _movement?.Teleport(playerPos);
            return;
        }

        // 寻找最近的敌人
        Transform nearestEnemy = FindNearestEnemy(pos);

        if (nearestEnemy != null)
        {
            Vector2 enemyPos = nearestEnemy.position;
            float distToEnemy = Vector2.Distance(pos, enemyPos);

            if (distToEnemy <= _attackRange)
            {
                _movement?.Stop();
                _attackBehavior?.TryAttack(nearestEnemy);

                // 尝试释放技能
                if (_skillManager != null && _skillManager.SkillInstances.Count > 0)
                {
                    Vector2 dir = (enemyPos - pos).normalized;
                    _skillManager.TryCastSkill(0, _core, dir);
                }
            }
            else
            {
                _movement?.MoveTowardsPosition(enemyPos);
            }
            return;
        }

        // 没有敌人 → 跟随玩家
        float distToPlayer = Vector2.Distance(pos, playerPos);
        if (distToPlayer > _followDistance)
        {
            _movement?.MoveTowardsPosition(playerPos);
        }
        else
        {
            _movement?.Stop();
        }
    }

    private Transform FindNearestEnemy(Vector2 center)
    {
        Collider2D[] hits = Physics2D.OverlapCircleAll(center, _detectionRange);
        Transform nearest = null;
        float minDist = float.MaxValue;

        foreach (var hit in hits)
        {
            if (!hit.CompareTag("Enemy")) continue;
            if (_player != null && hit.transform == _player) continue;

            float d = (hit.transform.position - (Vector3)center).sqrMagnitude;
            if (d < minDist)
            {
                minDist = d;
                nearest = hit.transform;
            }
        }

        return nearest;
    }

    private void HandleDeath()
    {
        _isActive = false;

        // 禁用碰撞
        foreach (var col in GetComponentsInChildren<Collider2D>())
            col.enabled = false;

        _movement?.Stop();
        Destroy(gameObject, 0.5f);
    }
}

